import CoreGraphics
import Foundation
import ImageIO

/// Courier props: the horse (express deliveries) and the mail (every
/// delivery), baked from embedded JPEGs. Mirrors the Windows port's
/// `src-win/build.rs`, which does this at compile time (chroma-key the flat
/// background out, crop to content, nearest-neighbour resize to a small
/// target, premultiplied RGBA with alpha 0/255); this project has no
/// asset-baking build step, so it's done once lazily at first use instead.
enum CourierProps {
    /// Target size mirrors `src-win/build.rs`'s `bake("../horse.jpg", "horse", 34, 24)`.
    static let horse: CGImage? = process(base64: horseJPEGBase64, targetWidth: 34, targetHeight: 24)
    /// Mirrors `bake("../mail.jpg", "mail", 20, 14)`.
    static let mail: CGImage? = process(base64: mailJPEGBase64, targetWidth: 20, targetHeight: 14)

    /// Display scale for each prop once baked - mirrors `HORSE_SCALE`/`MAIL_SCALE`
    /// in `src-win/src/main.rs`.
    static let horseScale = 3
    static let mailScale = 2

    private static func process(base64: String, targetWidth: Int, targetHeight: Int) -> CGImage? {
        guard let data = Data(base64Encoded: base64),
              let source = CGImageSourceCreateWithData(data as CFData, nil),
              let cgImage = CGImageSourceCreateImageAtIndex(source, 0, nil)
        else { return nil }

        let width = cgImage.width, height = cgImage.height
        guard width > 0, height > 0 else { return nil }

        var raw = [UInt8](repeating: 0, count: width * height * 4)
        guard let context = CGContext(
            data: &raw, width: width, height: height, bitsPerComponent: 8, bytesPerRow: width * 4,
            space: CGColorSpaceCreateDeviceRGB(),
            bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue
        ) else { return nil }
        context.draw(cgImage, in: CGRect(x: 0, y: 0, width: width, height: height))

        func pixel(_ x: Int, _ y: Int) -> (UInt8, UInt8, UInt8) {
            let o = (y * width + x) * 4
            return (raw[o], raw[o + 1], raw[o + 2])
        }
        // Background is whatever color sits at the top-left corner - same
        // heuristic as build.rs, since both source JPEGs are shot against a
        // flat backdrop.
        let bg = pixel(0, 0)
        func isBackground(_ p: (UInt8, UInt8, UInt8)) -> Bool {
            let d = abs(Int(p.0) - Int(bg.0)) + abs(Int(p.1) - Int(bg.1)) + abs(Int(p.2) - Int(bg.2))
            return d < 60
        }

        var minX = width, minY = height, maxX = -1, maxY = -1
        for y in 0..<height {
            for x in 0..<width where !isBackground(pixel(x, y)) {
                minX = min(minX, x); minY = min(minY, y)
                maxX = max(maxX, x); maxY = max(maxY, y)
            }
        }
        if maxX < minX {
            minX = 0; minY = 0; maxX = width - 1; maxY = height - 1
        }
        let cropWidth = maxX - minX + 1, cropHeight = maxY - minY + 1

        // Nearest-neighbour resize straight from the cropped region into the
        // target premultiplied-RGBA buffer, chroma-keying as we go.
        var out = [UInt8](repeating: 0, count: targetWidth * targetHeight * 4)
        for ty in 0..<targetHeight {
            let sy = minY + (ty * cropHeight) / targetHeight
            for tx in 0..<targetWidth {
                let sx = minX + (tx * cropWidth) / targetWidth
                let p = pixel(sx, sy)
                let o = (ty * targetWidth + tx) * 4
                if isBackground(p) {
                    out[o] = 0; out[o + 1] = 0; out[o + 2] = 0; out[o + 3] = 0
                } else {
                    out[o] = p.0; out[o + 1] = p.1; out[o + 2] = p.2; out[o + 3] = 255
                }
            }
        }

        guard let provider = CGDataProvider(data: Data(out) as CFData) else { return nil }
        return CGImage(
            width: targetWidth, height: targetHeight, bitsPerComponent: 8, bitsPerPixel: 32,
            bytesPerRow: targetWidth * 4, space: CGColorSpaceCreateDeviceRGB(),
            bitmapInfo: CGBitmapInfo(rawValue: CGImageAlphaInfo.premultipliedLast.rawValue),
            provider: provider, decode: nil, shouldInterpolate: false, intent: .defaultIntent
        )
    }

    // Repo-root `horse.jpg` / `mail.jpg`, base64-encoded - no bundle resources
    // or SwiftPM resource pipeline needed, matching the rest of this app's
    // pixel art (authored as compact Swift source, not loaded asset files).
    private static let horseJPEGBase64 = ""
    private static let mailJPEGBase64 = ""
}
